<?php $moduleTitle=ucfirst(str_replace('-',' ',$key)); ?>
<div class="admin-pagehead"><div><span class="micro-label">REGISTROS DEL SISTEMA</span><h1><?= e($moduleTitle) ?></h1><p>Consulta y gestiona los registros con trazabilidad desde el panel.</p></div><a class="btn btn-outline" href="/admin">← Inicio del panel</a></div>
<section class="admin-panel"><div class="panel-head"><h2>Últimos registros</h2><label class="mini-search">⌕ <input type="search" data-filter-table placeholder="Filtrar tabla..." aria-label="Filtrar registros"></label></div><div class="table-scroll"><table class="data-table" data-table><thead><tr><?php foreach($columns as $col):?><th><?= e(str_replace('_',' ',$col)) ?></th><?php endforeach ?><th>Gestión</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach($columns as $col):?><td><?= e(mb_substr((string)($row[$col]??''),0,110)) ?></td><?php endforeach ?><td>
