<?php elseif($key==='aportes'&&$row['estado']==='pendiente'):?><form class="inline-actions" method="post" action="/admin/aportes/<?= (int)$row['id'] ?>/estado"><?= csrf_field() ?><label class="inline-checkbox"><input name="conciliado" type="checkbox" value="1"> Ingreso conciliado</label><button name="estado" value="confirmado" data-confirm="Solo confirma si verificaste el ingreso efectivo en la cuenta o caja. ¿Continuar?">Confirmar</button><button name="estado" value="rechazado" data-confirm="¿Rechazar este registro?">Rechazar</button></form>
<?php else: ?><span class="muted">—</span><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php if(!$rows):?><div class="empty">Sin registros en este módulo.</div><?php endif ?></section>
